-- PT115-S4-Q8. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT115-S4-Q8$batch06$ AND q.stimulus=$batch06$Jorge: You won’t be able to write well about the rock music of the 1960s, since you were just an infant then. Rock music of the 1960s was created by and for people who were then in their teens and early twenties.
Ruth: Your reasoning is absurd. There are living writers who write well about ancient Roman culture, even though those writers are obviously not a part of ancient Roman culture. Why should my youth alone prevent me from writing well about the music of a period as recent as the 1960s?$batch06$ AND q.prompt=$batch06$Ruth responds to Jorge's criticism by$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT115-S4-Q8$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT115-S4-Q8$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Ruth) Her youth alone should not stop her from writing well about 1960s rock.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Some living writers write well about ancient Roman culture without having been part of it.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Jorge never says it, but his argument assumes you must have lived through a culture to write well about it. Ruth knocks that out with an analogy: writers on ancient Rome were obviously not there, and they write well.$batch06$), (3, $batch06$Goal$batch06$, $batch06$An analogy against Jorge's unstated assumption.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT115-S4-Q8$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Ruth does not dispute that she was an infant in the 1960s.$batch06$), ($batch06$B$batch06$, $batch06$No definition of popular culture is discussed.$batch06$), ($batch06$C$batch06$, $batch06$Ruth is not arguing that 1960s rock deserves serious study. She is arguing that she can write about it.$batch06$), ($batch06$D$batch06$, $batch06$The analogy is to writers on ancient Rome. The unstated assumption is that you have to have been part of a culture to write about it well.$batch06$), ($batch06$E$batch06$, $batch06$Ruth calls Jorge's reasoning absurd, but she never questions his qualifications.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT115-S4-Q8$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
